/**
 * @method
 * @name MxCombo_header_onselchange
 * @description 본부 콤보 선택 변경 — 최초 여부(ch_val)를 갱신하고 본부 선택 처리(comboHeader)를 수행한다.
 * @param {Object} info 선택 변경 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 * @example scwin.MxCombo_header_onselchange(info);
 */
scwin.MxCombo_header_onselchange = function(info) {
    try {
        if (scwin.ch_val > 0 || MxCombo_header.getSelectedIndex() > 0) {
            scwin.ch_val++;
            scwin.comboHeader(MxCombo_header.getSelectedIndex() + 1);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40008.MxCombo_header_onselchange" });
    }
};

