 */
scwin.grd_form_oncheckclick = function(rowIndex, columnIndex, columnId) {
    try {
        if (MxDataSet_dep_team.getCellData(MxCombo_team.getSelectedIndex() + 1, "dep_cd") === "0000") {
            alert("팀선정을 하시기 바랍니다.");
            MxDataSet_form.setCellData(col, "CHK_FLAG", 0);
        } else {
            scwin.dupleChek(col);
            // alert('grd_form.OnCheckClick('+col+','+ colid+','+ bCheck+')');

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT40008.grd_form_oncheckclick" });
    }
};

