 * @method
 * @name gform_onload
 * @description 구 gform onload 이관 함수 — 본부·부서·팀·팀별할당서식·서식 5개 데이터셋을 초기 조회하고 목록 동기화(listSync/formchrgteamSync/formlistSync)를 수행한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.gform_onload();
 */
scwin.gform_onload = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_dep_header",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_dep_header=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.MxDataSet_dep_header_OnLoadCompleted(sbmRtn); // 구 콜백 연결

    const sbmOptions2 = {
        id : "sbm_MxDataSet_dep_part",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_dep_part=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    scwin.MxDataSet_dep_part_OnLoadCompleted(sbmRtn2); // 구 콜백 연결

    const sbmOptions3 = {
        id : "sbm_MxDataSet_dep_team",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_dep_team=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    scwin.MxDataSet_dep_team_OnLoadCompleted(sbmRtn3); // 구 콜백 연결

    const sbmOptions4 = {
        id : "sbm_MxDataSet_chrgteam",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_chrgteam=body.content",
        isProcessMsg : false
    };

    const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
    scwin.MxDataSet_chrgteam_OnLoadCompleted(sbmRtn4); // 구 콜백 연결

    const sbmOptions5 = {
        id : "sbm_MxDataSet_form",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_form=body.content",
        isProcessMsg : false
    };

    const sbmRtn5 = await $c.sbm.executeDynamic(sbmOptions5);
    scwin.MxDataSet_form_OnLoadCompleted(sbmRtn5); // 구 콜백 연결

    // fn_list_sync_header();

    scwin.listSync();
    scwin.formchrgteamSync();
    scwin.formlistSync();
};
